import re


def eval_expression(expr):
    """Evaluate an arithmetic expression containing +, -, *, /, and parentheses."""

    number_pattern = re.compile(r"\d+(?:\.\d*)?|\.\d+")
    tokens = []
    i = 0

    # Tokenize the expression
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue

        match = number_pattern.match(expr, i)
        if match:
            text = match.group()
            tokens.append(float(text) if "." in text else int(text))
            i = match.end()
        elif expr[i] in "+-*/()":
            tokens.append(expr[i])
            i += 1
        else:
            raise ValueError(f"Invalid character: {expr[i]!r}")

    position = 0

    def peek():
        return tokens[position] if position < len(tokens) else None

    def consume():
        nonlocal position
        token = peek()
        position += 1
        return token

    def parse_expression():
        value = parse_term()

        while peek() in ("+", "-"):
            operator = consume()
            right = parse_term()
            value = value + right if operator == "+" else value - right

        return value

    def parse_term():
        value = parse_factor()

        while peek() in ("*", "/"):
            operator = consume()
            right = parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def parse_factor():
        token = peek()

        # Support unary plus and minus, including expressions like -(-3)
        if token == "+":
            consume()
            return parse_factor()
        if token == "-":
            consume()
            return -parse_factor()

        if token == "(":
            consume()
            value = parse_expression()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            consume()
            return value

        if isinstance(token, (int, float)):
            consume()
            return token

        raise ValueError("Expected a number or opening parenthesis")

    if not tokens:
        raise ValueError("Expression is empty")

    result = parse_expression()

    if position != len(tokens):
        raise ValueError(f"Unexpected token: {peek()!r}")

    return result
